window.PS_EXAMPLES = [
 {
  "file": "01_vector_add.psa",
  "src": "; =============================================================================\n; 01 vector_add — the \"hello world\" of GPU computing\n; -----------------------------------------------------------------------------\n; CUDA version:\n;   __global__ void vadd(const int* A, const int* B, int* C, int n) {\n;       int i = blockIdx.x * blockDim.x + threadIdx.x;\n;       if (i >= n) return;\n;       C[i] = A[i] + B[i];\n;   }\n;   vadd<<<4, 16>>>(A, B, C, 64);\n;\n; Watch for: every lane runs the SAME instruction on DIFFERENT data (SIMT),\n; and the 8 loads of a warp collapse into 2 memory transactions (coalescing).\n; =============================================================================\n.kernel vector_add\n.grid 4\n.block 16\n.equ N, 64\n.equ A, 0x000\n.equ B, 0x100\n.equ C, 0x200\n.param 0, A          ; kernel arguments go to constant bank c[0..3]\n.param 1, B\n.param 2, C\n.param 3, N\n.seq  A, N, 0, 1     ; A[i] = i\n.seq  B, N, 100, 10  ; B[i] = 100 + 10*i\n.dump C, N, C = A + B\n.note Every thread computes one element. The grid covers all 64 elements.\n\n    S2R   R0, CTAID          ; R0 = blockIdx.x\n    S2R   R1, NTID           ; R1 = blockDim.x\n    S2R   R2, TID            ; R2 = threadIdx.x\n    MAD   R3, R0, R1, R2     ; R3 = i = blockIdx.x * blockDim.x + threadIdx.x\n    LDC   R4, c[3]           ; R4 = n\n    SETP.GE P0, R3, R4       ; P0 = (i >= n)\n@P0 EXIT                     ; out-of-range threads leave early\n    LDC   R5, c[0]           ; &A\n    LDC   R6, c[1]           ; &B\n    LDC   R7, c[2]           ; &C\n    ADD   R5, R5, R3         ; &A[i]\n    ADD   R6, R6, R3         ; &B[i]\n    ADD   R7, R7, R3         ; &C[i]\n    LDG   R8, [R5]           ; A[i]   (global load, coalesced)\n    LDG   R9, [R6]           ; B[i]\n    ADD   R10, R8, R9\n    STG   [R7], R10          ; C[i] = A[i] + B[i]\n    EXIT\n"
 },
 {
  "file": "02_saxpy_fixed.psa",
  "src": "; =============================================================================\n; 02 saxpy_fixed — y = a*x + y   (the classic BLAS level-1 kernel)\n; -----------------------------------------------------------------------------\n; Real GPUs do this in 32-bit floating point with one FFMA per element.\n; Pixelstorm is integer-only, so we use Q16.16 fixed point: the value v is\n; stored as v * 65536. QMUL multiplies two Q16.16 numbers.\n;\n;   __global__ void saxpy(int n, float a, const float* x, float* y) {\n;       int i = blockIdx.x * blockDim.x + threadIdx.x;\n;       if (i < n) y[i] = a * x[i] + y[i];\n;   }\n; =============================================================================\n.kernel saxpy_fixed\n.grid 2\n.block 32\n.equ N, 64\n.equ X, 0x000\n.equ Y, 0x100\n.equ ONE, 65536\n.param 0, X\n.param 1, Y\n.param 2, N\n.param 3, 163840       ; a = 2.5 in Q16.16\n.seq  X, N, 0, ONE     ; x[i] = i.0\n.fill Y, N, ONE        ; y[i] = 1.0\n.dump Y, N, y = 2.5*x + 1  (Q16.16, divide by 65536)\n\n    S2R   R0, CTAID\n    S2R   R1, NTID\n    S2R   R2, TID\n    MAD   R3, R0, R1, R2       ; i\n    LDC   R4, c[2]\n    SETP.GE P0, R3, R4\n@P0 EXIT\n    LDC   R5, c[0]\n    ADD   R5, R5, R3           ; &x[i]\n    LDC   R6, c[1]\n    ADD   R6, R6, R3           ; &y[i]\n    LDC   R7, c[3]             ; a\n    LDG   R8, [R5]             ; x[i]\n    LDG   R9, [R6]             ; y[i]\n    QMUL  R10, R7, R8          ; a * x[i]      (fixed-point multiply)\n    ADD   R10, R10, R9         ; + y[i]\n    STG   [R6], R10\n    EXIT\n"
 },
 {
  "file": "03_divergence.psa",
  "src": "; =============================================================================\n; 03 divergence — what happens when threads of one warp disagree\n; -----------------------------------------------------------------------------\n;   int v;\n;   if (i & 1) v = i * 3;        // odd lanes\n;   else       v = i >> 1;       // even lanes\n;   for (int k = 0; k < (i & 3); k++) v += 10;   // different trip counts!\n;   out[i] = v;\n;\n; Watch the \"active mask\" in the visualizer: the warp runs the odd path with\n; half its lanes, then the even path with the other half, then both halves\n; reconverge. Inside the loop lanes drop out one by one. Every idle lane is\n; wasted hardware — that is the cost of divergence.\n; =============================================================================\n.kernel divergence\n.grid 1\n.block 16\n.equ OUT, 0x300\n.param 0, OUT\n.dump OUT, 16, out[i]\n\n    S2R   R0, TID              ; i (one block, so TID is the global id)\n    ANDI  R1, R0, 1\n    MOVI  R2, 0\n    SETP.NE P0, R1, R2         ; P0 = odd?\n@!P0 BRA even\n    MULI  R3, R0, 3            ; odd path\n    BRA   join\neven:\n    SHRI  R3, R0, 1            ; even path\njoin:                          ; <- lanes reconverge here (min-PC)\n    ANDI  R4, R0, 3            ; trip count = i & 3\n    MOVI  R5, 0                ; k = 0\nloop:\n    SETP.GE P1, R5, R4\n@P1 BRA done                   ; lanes leave the loop at different times\n    ADDI  R3, R3, 10\n    ADDI  R5, R5, 1\n    BRA   loop\ndone:\n    LDC   R6, c[0]\n    ADD   R6, R6, R0\n    STG   [R6], R3\n    EXIT\n"
 },
 {
  "file": "04_reduction_shared.psa",
  "src": "; =============================================================================\n; 04 reduction_shared — block-wide sum with shared memory and __syncthreads()\n; -----------------------------------------------------------------------------\n;   __global__ void reduce(const int* in, int* out) {\n;       __shared__ int s[32];\n;       int t = threadIdx.x;\n;       s[t] = in[blockIdx.x * blockDim.x + t];\n;       __syncthreads();\n;       for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {\n;           if (t < stride) s[t] += s[t + stride];\n;           __syncthreads();\n;       }\n;       if (t == 0) out[blockIdx.x] = s[0];\n;   }\n;\n; A block of 32 threads is 4 warps. BAR parks each warp until all 4 arrive,\n; so no warp reads a partial sum that another warp has not written yet.\n; =============================================================================\n.kernel reduction_shared\n.grid 4\n.block 32\n.equ IN,  0x000\n.equ OUT, 0x400\n.param 0, IN\n.param 1, OUT\n.seq  IN, 128, 1, 1          ; 1, 2, 3, ... 128\n.dump OUT, 4, per-block sums (block b = sum of 32b+1 .. 32b+32)\n\n    S2R   R0, TID\n    S2R   R1, CTAID\n    S2R   R2, NTID\n    MAD   R3, R1, R2, R0        ; global index\n    LDC   R4, c[0]\n    ADD   R4, R4, R3\n    LDG   R5, [R4]\n    STS   [R0], R5              ; s[t] = in[i]\n    BAR                         ; __syncthreads()\n    SHRI  R6, R2, 1             ; stride = blockDim / 2\n    MOVI  R10, 0\nloop:\n    SETP.LT P0, R0, R6          ; active = t < stride   (predication, no branch)\n    ADD   R7, R0, R6\n@P0 LDS   R8, [R7]\n@P0 LDS   R9, [R0]\n@P0 ADD   R9, R9, R8\n@P0 STS   [R0], R9\n    BAR\n    SHRI  R6, R6, 1\n    SETP.GT P1, R6, R10\n@P1 BRA   loop                  ; uniform branch: every lane agrees\n    SETP.EQ P2, R0, R10\n@!P2 EXIT\n    LDS   R11, [R0]\n    LDC   R12, c[1]\n    ADD   R12, R12, R1\n    STG   [R12], R11            ; out[blockIdx.x] = s[0]\n    EXIT\n"
 },
 {
  "file": "05_reduction_shuffle.psa",
  "src": "; =============================================================================\n; 05 reduction_shuffle — warp-level sum with SHFL.DOWN, then one atomic per warp\n; -----------------------------------------------------------------------------\n;   int v = in[i];\n;   for (int off = 4; off > 0; off >>= 1)          // warp size 8 here\n;       v += __shfl_down_sync(0xff, v, off);\n;   if ((threadIdx.x & 7) == 0) atomicAdd(out, v);\n;\n; No shared memory, no barrier: registers move directly between lanes.\n; =============================================================================\n.kernel reduction_shuffle\n.grid 4\n.block 32\n.equ IN,  0x000\n.equ OUT, 0x500\n.param 0, IN\n.param 1, OUT\n.seq  IN, 128, 1, 1\n.dump OUT, 1, total = 128*129/2 = 8256\n\n    S2R   R0, TID\n    S2R   R1, CTAID\n    S2R   R2, NTID\n    MAD   R3, R1, R2, R0\n    LDC   R4, c[0]\n    ADD   R4, R4, R3\n    LDG   R5, [R4]\n    SHFL.DOWN R6, R5, 4          ; lane l gets v from lane l+4\n    ADD   R5, R5, R6\n    SHFL.DOWN R6, R5, 2\n    ADD   R5, R5, R6\n    SHFL.DOWN R6, R5, 1\n    ADD   R5, R5, R6             ; lane 0 now holds the warp's sum\n    S2R   R7, LANEID\n    MOVI  R8, 0\n    SETP.NE P0, R7, R8\n@P0 EXIT\n    LDC   R9, c[1]\n    ATOM.ADD R10, [R9], R5       ; out[0] += warp sum\n    EXIT\n"
 },
 {
  "file": "06_histogram.psa",
  "src": "; =============================================================================\n; 06 histogram — many threads updating the same counters: atomics\n; -----------------------------------------------------------------------------\n;   int v = data[i];           // values 0..15\n;   atomicAdd(&bins[v], 1);\n;\n; Without ATOM two lanes could read the same old count and both write +1,\n; losing an update. ATOM.ADD serializes lanes inside the memory system.\n; =============================================================================\n.kernel histogram\n.grid 4\n.block 32\n.equ DATA, 0x000\n.equ BINS, 0x600\n.param 0, DATA\n.param 1, BINS\n.rand DATA, 128, 7, 16        ; 128 pseudo-random values in 0..15\n.dump BINS, 16, histogram bins\n\n    S2R   R0, TID\n    S2R   R1, CTAID\n    S2R   R2, NTID\n    MAD   R3, R1, R2, R0\n    LDC   R4, c[0]\n    ADD   R4, R4, R3\n    LDG   R5, [R4]               ; bin index\n    LDC   R6, c[1]\n    ADD   R6, R6, R5             ; &bins[v]\n    MOVI  R7, 1\n    ATOM.ADD R8, [R6], R7        ; R8 = old count (unused)\n    EXIT\n"
 },
 {
  "file": "07_matmul.psa",
  "src": "; =============================================================================\n; 07 matmul — C = A x B for 8x8 matrices, one thread per output element\n; -----------------------------------------------------------------------------\n;   int row = i / 8, col = i % 8, acc = 0;\n;   for (int k = 0; k < 8; k++) acc += A[row*8 + k] * B[k*8 + col];\n;   C[i] = acc;\n;\n; The inner loop is one MAD per iteration — the multiply-accumulate that\n; Tensor Cores do thousands of at once. Note the access patterns: within a\n; warp every lane reads the SAME A element (a broadcast, 1 transaction) and\n; 8 consecutive B elements (coalesced, 2 transactions).\n; =============================================================================\n.kernel matmul\n.grid 2\n.block 32\n.equ A, 0x000\n.equ B, 0x040\n.equ C, 0x080\n.param 0, A\n.param 1, B\n.param 2, C\n.seq  A, 64, 1, 1              ; A = 1..64 row-major\n.seq  B, 64, 0, 1              ; B = 0..63 row-major\n.dump C, 64, C = A x B (8x8)\n\n    S2R   R0, CTAID\n    S2R   R1, NTID\n    S2R   R2, TID\n    MAD   R3, R0, R1, R2        ; i\n    SHRI  R4, R3, 3             ; row\n    ANDI  R5, R3, 7             ; col\n    LDC   R6, c[0]\n    SHLI  R7, R4, 3\n    ADD   R6, R6, R7            ; &A[row][0]\n    LDC   R7, c[1]\n    ADD   R7, R7, R5            ; &B[0][col]\n    MOVI  R8, 0                 ; acc\n    MOVI  R9, 0                 ; k\n    MOVI  R13, 8\nkloop:\n    LDG   R10, [R6]             ; A[row][k]\n    LDG   R11, [R7]             ; B[k][col]\n    MAD   R8, R10, R11, R8      ; acc += a * b\n    ADDI  R6, R6, 1\n    ADDI  R7, R7, 8\n    ADDI  R9, R9, 1\n    SETP.LT P0, R9, R13\n@P0 BRA   kloop\n    LDC   R12, c[2]\n    ADD   R12, R12, R3\n    STG   [R12], R8\n    EXIT\n"
 },
 {
  "file": "08_coalescing.psa",
  "src": "; =============================================================================\n; 08 coalescing — same amount of data, very different memory traffic\n; -----------------------------------------------------------------------------\n; Load 1: lane l reads in[i]        -> 8 lanes hit 2 cache lines  = 2 transactions\n; Load 2: lane l reads in[i * 4]    -> 8 lanes hit 8 cache lines  = 8 transactions\n; Load 3: every lane reads in[0]    -> 1 line, broadcast           = 1 transaction\n;\n; Compare the \"txn\" and \"MEM cycles\" of the three LDG instructions in the\n; visualizer. This is why CUDA programmers obsess over data layout\n; (structure-of-arrays vs array-of-structures).\n; =============================================================================\n.kernel coalescing\n.grid 1\n.block 8\n.equ IN,  0x000\n.equ OUT, 0x700\n.param 0, IN\n.param 1, OUT\n.seq  IN, 64, 0, 1\n.dump OUT, 24, [contiguous x8][strided x8][broadcast x8]\n\n    S2R   R0, TID\n    LDC   R1, c[0]\n    ADD   R2, R1, R0\n    LDG   R3, [R2]              ; contiguous\n    SHLI  R4, R0, 2\n    ADD   R4, R1, R4\n    LDG   R5, [R4]              ; stride 4\n    LDG   R6, [R1]              ; broadcast\n    LDC   R7, c[1]\n    ADD   R7, R7, R0\n    STG   [R7], R3\n    STG   [R7+8], R5\n    STG   [R7+16], R6\n    EXIT\n"
 },
 {
  "file": "09_bank_conflicts.psa",
  "src": "; =============================================================================\n; 09 bank_conflicts — shared memory has 8 banks; one word per bank per cycle\n; -----------------------------------------------------------------------------\n; Access 1: s[t]        -> 8 different banks          -> 1 pass\n; Access 2: s[t * 8]    -> all lanes hit bank 0       -> 8 passes (8-way conflict)\n; Access 3: s[5]        -> same word for everyone     -> 1 pass (broadcast)\n; Access 4: s[t * 2]    -> pairs of lanes share banks -> 2 passes\n; =============================================================================\n.kernel bank_conflicts\n.grid 1\n.block 8\n.equ OUT, 0x780\n.param 0, OUT\n.dump OUT, 32, [s[t]][s[8t]][s[5]][s[2t]]\n\n    S2R   R0, TID\n    MULI  R1, R0, 100\n    SHLI  R2, R0, 3             ; 8t\n    STS   [R2], R1              ; fill s[8t] = 100t   (8-way conflict on store)\n    STS   [R0+64], R1           ; s[64+t]             (conflict-free)\n    MOVI  R9, 5\n    STS   [R9], R9              ; everyone writes s[5] = 5 (same word)\n    LDS   R3, [R0+64]           ; 1 pass\n    LDS   R4, [R2]              ; 8 passes\n    LDS   R5, [R9]              ; broadcast, 1 pass\n    SHLI  R6, R0, 1\n    LDS   R7, [R6+64]           ; stride 2: 2 passes\n    LDC   R8, c[0]\n    ADD   R8, R8, R0\n    STG   [R8], R3\n    STG   [R8+8], R4\n    STG   [R8+16], R5\n    STG   [R8+24], R7\n    EXIT\n"
 },
 {
  "file": "10_vote_ballot.psa",
  "src": "; =============================================================================\n; 10 vote_ballot — warp-wide decisions in one instruction\n; -----------------------------------------------------------------------------\n;   bool big = v > 50;\n;   unsigned m = __ballot_sync(0xff, big);   // bit l set if lane l voted yes\n;   int count  = __popc(m);\n;   bool any   = __any_sync(0xff, big);\n;   bool all   = __all_sync(0xff, big);\n; Lane 0 of each warp writes [ballot, count, any, all].\n; =============================================================================\n.kernel vote_ballot\n.grid 1\n.block 32\n.equ IN,  0x000\n.equ OUT, 0x7C0\n.param 0, IN\n.param 1, OUT\n.rand IN, 32, 3, 100\n.dump OUT, 16, per warp: ballot mask, popcount, any, all\n\n    S2R   R0, TID\n    LDC   R1, c[0]\n    ADD   R1, R1, R0\n    LDG   R2, [R1]\n    MOVI  R3, 50\n    SETP.GT P0, R2, R3          ; my vote\n    VOTE.BALLOT R4, P0\n    POPC  R5, R4\n    VOTE.ANY P1, P0\n    VOTE.ALL P2, P0\n    MOVI  R6, 1\n    MOVI  R7, 0\n    SEL   R8, R6, R7, P1        ; any -> 0/1\n    SEL   R9, R6, R7, P2        ; all -> 0/1\n    S2R   R10, LANEID\n    SETP.NE P3, R10, R7\n@P3 EXIT\n    S2R   R11, WARPID\n    SHLI  R11, R11, 2\n    LDC   R12, c[1]\n    ADD   R12, R12, R11\n    STG   [R12], R4\n    STG   [R12+1], R5\n    STG   [R12+2], R8\n    STG   [R12+3], R9\n    EXIT\n"
 },
 {
  "file": "11_prefix_scan.psa",
  "src": "; =============================================================================\n; 11 prefix_scan — inclusive scan inside each warp (Hillis-Steele with SHFL.UP)\n; -----------------------------------------------------------------------------\n;   for (int d = 1; d < 8; d <<= 1) {\n;       int n = __shfl_up_sync(0xff, v, d);\n;       if (lane >= d) v += n;\n;   }\n; Scans are the building block of stream compaction, radix sort and\n; sparse-matrix kernels.\n; =============================================================================\n.kernel prefix_scan\n.grid 2\n.block 16\n.equ IN,  0x000\n.equ OUT, 0x800\n.param 0, IN\n.param 1, OUT\n.fill IN, 32, 1                 ; all ones -> output is 1,2,...,8 per warp\n.dump OUT, 32, inclusive scan per warp\n\n    S2R   R0, CTAID\n    S2R   R1, NTID\n    S2R   R2, TID\n    MAD   R3, R0, R1, R2\n    LDC   R4, c[0]\n    ADD   R4, R4, R3\n    LDG   R5, [R4]\n    S2R   R6, LANEID\n    MOVI  R9, 1\n    SETP.GE P0, R6, R9\n    SHFL.UP R7, R5, 1\n@P0 ADD   R5, R5, R7\n    MOVI  R9, 2\n    SETP.GE P0, R6, R9\n    SHFL.UP R7, R5, 2\n@P0 ADD   R5, R5, R7\n    MOVI  R9, 4\n    SETP.GE P0, R6, R9\n    SHFL.UP R7, R5, 4\n@P0 ADD   R5, R5, R7\n    LDC   R8, c[1]\n    ADD   R8, R8, R3\n    STG   [R8], R5\n    EXIT\n"
 },
 {
  "file": "12_threshold_image.psa",
  "src": "; =============================================================================\n; 12 threshold_image — an 8x8 \"image\" turned black/white, branch-free\n; -----------------------------------------------------------------------------\n;   out[p] = (in[p] > 128) ? 255 : 0;     // SEL instead of if/else\n; Branch-free code keeps every lane active: no divergence at all.\n; Graphics shaders are full of this pattern.\n; =============================================================================\n.kernel threshold_image\n.grid 2\n.block 32\n.equ IN,  0x000\n.equ OUT, 0x900\n.param 0, IN\n.param 1, OUT\n.rand IN, 64, 11, 256\n.dump OUT, 64, thresholded 8x8 image\n\n    S2R   R0, CTAID\n    S2R   R1, NTID\n    S2R   R2, TID\n    MAD   R3, R0, R1, R2\n    LDC   R4, c[0]\n    ADD   R4, R4, R3\n    LDG   R5, [R4]\n    MOVI  R6, 128\n    SETP.GT P0, R5, R6\n    MOVI  R7, 255\n    MOVI  R8, 0\n    SEL   R9, R7, R8, P0\n    LDC   R10, c[1]\n    ADD   R10, R10, R3\n    STG   [R10], R9\n    EXIT\n"
 },
 {
  "file": "13_gradient_shader.psa",
  "src": "; 13 gradient_shader — the \"hello world\" of shaders: every thread colors one pixel\n; -----------------------------------------------------------------------------\n; A pixel (fragment) shader is a small program that runs once per pixel. On a\n; GPU that means one thread per pixel: the whole image is one big grid launch.\n; Here: a 32 x 32 image, one block per row, one thread per column.\n;\n; GLSL-style version:\n;   vec3 color = vec3(x / 32.0, y / 32.0, 1.0 - (x + y) / 64.0);\n; CUDA version:\n;   __global__ void shade(uint32_t* fb) {\n;       int x = threadIdx.x, y = blockIdx.x;\n;       int r = x * 8, g = y * 8, b = max(0, 255 - 4 * (x + y));\n;       fb[y * 32 + x] = (r << 16) | (g << 8) | b;\n;   }\n;\n; Watch for: zero divergence, perfectly coalesced stores, and the framebuffer\n; panel in the visualizer filling row by row as blocks finish.\n; =============================================================================\n.kernel gradient_shader\n.grid 32                       ; one block per row\n.block 32                      ; one thread per column (4 warps of 8)\n.equ W, 32\n.equ H, 32\n.equ FB, 0x1000\n.param 0, FB\n.fb FB, W, H                   ; show this memory as an image\n\n    S2R  R0, CTAID             ; y = blockIdx.x\n    S2R  R1, TID               ; x = threadIdx.x\n    SHLI R2, R1, 3             ; red   = x * 8\n    SHLI R3, R0, 3             ; green = y * 8\n    ADD  R4, R1, R0\n    SHLI R4, R4, 2             ; 4 * (x + y)\n    MOVI R5, 255\n    SUB  R4, R5, R4            ; blue = 255 - 4 * (x + y)\n    MOVI R6, 0\n    MAX  R4, R4, R6            ; clamp at 0\n    SHLI R2, R2, 16            ; pack 0x00RRGGBB\n    SHLI R3, R3, 8\n    OR   R2, R2, R3\n    OR   R2, R2, R4\n    SHLI R7, R0, 5             ; y * 32\n    ADD  R7, R7, R1            ; + x = pixel index\n    LDC  R8, c[0]\n    ADD  R8, R8, R7            ; &fb[y * W + x]\n    STG  [R8], R2\n    EXIT\n"
 },
 {
  "file": "14_triangle_raster.psa",
  "src": "; 14 triangle_raster — how a GPU draws a triangle: edge functions per pixel\n; -----------------------------------------------------------------------------\n; Every 3D image is made of triangles. Rasterization asks, for each pixel:\n; is its center inside the triangle? GPUs answer with three EDGE FUNCTIONS\n; (Pineda, 1988). For an edge V0 -> V1 and a pixel P:\n;\n;     E(P) = (V1y - V0y) * Px  -  (V1x - V0x) * Py  +  (V0y*(V1x - V0x) - V0x*(V1y - V0y))\n;\n; E >= 0 on the inner side of the edge. Inside the triangle all three are >= 0,\n; and each E divided by the triangle's area is a BARYCENTRIC weight: how close\n; P is to the opposite corner. Blending red, green and blue by those weights\n; gives the famous \"hello triangle\".\n;\n; Coordinates are doubled (half-pixel units) so pixel centers 2x+1 are integers.\n; The per-edge coefficients are computed by the assembler (.equ) and passed as\n; kernel arguments, exactly like a driver sets up a real rasterizer.\n;\n; CUDA version:\n;   __global__ void raster(uint32_t* fb, Edge e[3], int k, uint32_t bg) {\n;       int px = 2 * threadIdx.x + 1, py = 2 * blockIdx.x + 1;\n;       int w[3]; for (int i = 0; i < 3; i++) w[i] = e[i].a * px + e[i].b * py + e[i].c;\n;       bool inside = min(w[0], min(w[1], w[2])) >= 0;\n;       uint32_t rgb = ((w[0] * k) >> 16) << 16 | ((w[1] * k) >> 16) << 8 | ((w[2] * k) >> 16);\n;       fb[blockIdx.x * 32 + threadIdx.x] = inside ? rgb : bg;\n;   }\n;\n; Watch for: no branches at all. Inside/outside is a predicate (@!P0 MOV),\n; so every warp stays converged even along the triangle's edges.\n; =============================================================================\n.kernel triangle_raster\n.grid 32\n.block 32\n.equ W, 32\n.equ FB, 0x1000\n.equ BG, 0x101828              ; dark background\n; vertices in half-pixel units: A (top, red), B (bottom right, green), C (bottom left, blue)\n.equ AX, 32\n.equ AY, 4\n.equ BX, 60\n.equ BY, 58\n.equ CX, 4\n.equ CY, 52\n; edge opposite A is C -> B, opposite B is A -> C, opposite C is B -> A\n.equ EA_A, BY - CY\n.equ EA_B, -(BX - CX)\n.equ EA_C, CY * (BX - CX) - CX * (BY - CY)\n.equ EB_A, CY - AY\n.equ EB_B, -(CX - AX)\n.equ EB_C, AY * (CX - AX) - AX * (CY - AY)\n.equ EC_A, AY - BY\n.equ EC_B, -(AX - BX)\n.equ EC_C, BY * (AX - BX) - BX * (AY - BY)\n.equ AREA, EA_A * AX + EA_B * AY + EA_C      ; weight of A at A = twice the area\n.equ KCOL, 255 * 65536 / AREA                ; weight -> 0..255 via one QMUL\n.param 0, EA_A\n.param 1, EA_B\n.param 2, EA_C\n.param 3, EB_A\n.param 4, EB_B\n.param 5, EB_C\n.param 6, EC_A\n.param 7, EC_B\n.param 8, EC_C\n.param 9, FB\n.param 10, KCOL\n.param 11, BG\n.fb FB, W, W\n\n    S2R  R0, TID\n    SHLI R0, R0, 1\n    ADDI R0, R0, 1             ; Px = 2x + 1 (pixel center)\n    S2R  R1, CTAID\n    SHLI R1, R1, 1\n    ADDI R1, R1, 1             ; Py = 2y + 1\n    LDC  R5, c[0]              ; --- edge opposite A: weight of red\n    LDC  R6, c[1]\n    LDC  R7, c[2]\n    MUL  R6, R6, R1\n    ADD  R6, R6, R7\n    MAD  R2, R5, R0, R6        ; wA = a*Px + b*Py + c\n    LDC  R5, c[3]              ; --- edge opposite B: weight of green\n    LDC  R6, c[4]\n    LDC  R7, c[5]\n    MUL  R6, R6, R1\n    ADD  R6, R6, R7\n    MAD  R3, R5, R0, R6        ; wB\n    LDC  R5, c[6]              ; --- edge opposite C: weight of blue\n    LDC  R6, c[7]\n    LDC  R7, c[8]\n    MUL  R6, R6, R1\n    ADD  R6, R6, R7\n    MAD  R4, R5, R0, R6        ; wC\n    MIN  R5, R2, R3            ; inside if min(wA, wB, wC) >= 0\n    MIN  R5, R5, R4\n    MOVI R6, 0\n    SETP.GE P0, R5, R6\n    LDC  R7, c[10]             ; 255 / area as Q16.16\n    QMUL R2, R2, R7            ; red   = wA * 255 / area\n    QMUL R3, R3, R7            ; green = wB * 255 / area\n    QMUL R4, R4, R7            ; blue  = wC * 255 / area\n    SHLI R2, R2, 16\n    SHLI R3, R3, 8\n    OR   R2, R2, R3\n    OR   R2, R2, R4\n    LDC  R8, c[11]\n@!P0 MOV R2, R8                ; outside: background (predicated, no branch)\n    S2R  R9, CTAID\n    SHLI R9, R9, 5\n    S2R  R10, TID\n    ADD  R9, R9, R10           ; pixel index y * 32 + x\n    LDC  R11, c[9]\n    ADD  R11, R11, R9\n    STG  [R11], R2\n    EXIT\n"
 },
 {
  "file": "15_mandelbrot.psa",
  "src": "; 15 mandelbrot — the Mandelbrot set: beautiful, and the textbook case of divergence\n; -----------------------------------------------------------------------------\n; Each pixel is a complex number c. Iterate z = z*z + c from z = 0 and count\n; the steps until |z| > 2 (it \"escapes\"). Points that never escape are in the\n; set (black); the rest are colored by how fast they escaped.\n;\n; Every lane iterates a DIFFERENT number of times. A warp keeps issuing the\n; loop until its slowest lane is done, with the finished lanes idle. Along the\n; edge of the set, neighbouring pixels differ wildly, so SIMD efficiency drops.\n; (Try the \"Pixels and warps\" lab to see how warp shape changes this.)\n;\n; Arithmetic is Q16.16 fixed point: 1.0 = 65536, QMUL = (a * b) >> 16.\n; The image is 32 x 16 pixels covering x in [-2.5, 1.5], y in [-1, 1].\n;\n; CUDA version:\n;   __global__ void mandel(uint32_t* fb, float x0, float y0, float step, int maxit) {\n;       float cx = x0 + threadIdx.x * step, cy = y0 + blockIdx.x * step;\n;       float zx = 0, zy = 0; int it = 0;\n;       while (zx*zx + zy*zy <= 4.0f && it < maxit) {\n;           float t = zx*zx - zy*zy + cx; zy = 2*zx*zy + cy; zx = t; it++;\n;       }\n;       fb[blockIdx.x * 32 + threadIdx.x] = it == maxit ? 0 : palette(it);\n;   }\n; =============================================================================\n.kernel mandelbrot\n.grid 16                       ; 16 rows\n.block 32                      ; 32 columns\n.equ W, 32\n.equ H, 16\n.equ FB, 0x1000\n.equ ONE, 65536                ; 1.0 in Q16.16\n.equ STEP, ONE / 8             ; 0.125 per pixel\n.equ MAXIT, 12\n.param 0, FB\n.equ X0, STEP / 2 - 5 * ONE / 2      ; x of the first pixel center (-2.4375)\n.equ Y0, STEP / 2 - ONE              ; y of the first pixel center (-0.9375)\n.param 1, X0\n.param 2, Y0\n.param 3, STEP\n.param 4, MAXIT\n.param 5, 4 * ONE                     ; escape radius squared\n.fb FB, W, H\n\n    S2R  R0, TID               ; x\n    S2R  R1, CTAID             ; y\n    LDC  R9, c[3]\n    LDC  R2, c[1]\n    MAD  R2, R0, R9, R2        ; cx = x0 + x * step\n    LDC  R3, c[2]\n    MAD  R3, R1, R9, R3        ; cy = y0 + y * step\n    MOVI R4, 0                 ; zx\n    MOVI R5, 0                 ; zy\n    MOVI R6, 0                 ; iteration count\n    LDC  R10, c[5]             ; 4.0\n    LDC  R11, c[4]             ; max iterations\nloop:\n    QMUL R7, R4, R4            ; zx^2\n    QMUL R8, R5, R5            ; zy^2\n    ADD  R9, R7, R8\n    SETP.GT P0, R9, R10        ; escaped?\n    SETP.GE P1, R6, R11        ; out of iterations?\n@P0 BRA  done                  ; <- lanes leave the loop at different times\n@P1 BRA  done\n    QMUL R9, R4, R5\n    SHLI R9, R9, 1             ; 2 * zx * zy\n    ADD  R5, R9, R3            ; zy = 2 zx zy + cy\n    SUB  R4, R7, R8\n    ADD  R4, R4, R2            ; zx = zx^2 - zy^2 + cx\n    ADDI R6, R6, 1\n    BRA  loop\ndone:                          ; min-PC scheduling reconverges the warp here\n    MOVI R9, 255\n    MULI R7, R6, 24\n    MIN  R7, R7, R9            ; red   = min(255, 24 * it)\n    MULI R8, R6, 10            ; green = 10 * it\n    MULI R12, R6, 12\n    MOVI R13, 170\n    SUB  R12, R13, R12\n    MOVI R13, 0\n    MAX  R12, R12, R13         ; blue  = max(0, 170 - 12 * it)\n    SHLI R7, R7, 16\n    SHLI R8, R8, 8\n    OR   R7, R7, R8\n    OR   R7, R7, R12\n    SETP.GE P2, R6, R11\n@P2 MOVI R7, 0                 ; never escaped: inside the set, black\n    SHLI R9, R1, 5\n    ADD  R9, R9, R0            ; pixel index\n    LDC  R13, c[0]\n    ADD  R13, R13, R9\n    STG  [R13], R7\n    EXIT\n"
 },
 {
  "file": "16_matmul_cached.psa",
  "src": "; 16 matmul_cached — the same matrix multiply, on a GPU with a 16-line cache\n; -----------------------------------------------------------------------------\n; Identical instructions to 07_matmul. The only change is .cache 16: a small\n; direct-mapped cache (rtl/ps_cache.v) sits between the memory arbiter and\n; DRAM. Every row of A and column of B is read by many threads, so most loads\n; hit the cache and never reach DRAM. Compare the cycle counts:\n;     ./pixelstorm rtl matmul          ./pixelstorm rtl matmul_cached\n; A streaming kernel (13_gradient_shader) gets slightly slower with the same\n; cache: with no reuse, every access pays for the extra hop. That trade-off is\n; why real GPUs let programs choose how to use their caches.\n; =============================================================================\n.kernel matmul_cached\n.cache 16                      ; <- the only difference from 07_matmul\n.grid 2\n.block 32\n.equ A, 0x000\n.equ B, 0x040\n.equ C, 0x080\n.param 0, A\n.param 1, B\n.param 2, C\n.seq  A, 64, 1, 1              ; A = 1..64 row-major\n.seq  B, 64, 0, 1              ; B = 0..63 row-major\n.dump C, 64, C = A x B (8x8)\n\n    S2R   R0, CTAID\n    S2R   R1, NTID\n    S2R   R2, TID\n    MAD   R3, R0, R1, R2        ; i\n    SHRI  R4, R3, 3             ; row\n    ANDI  R5, R3, 7             ; col\n    LDC   R6, c[0]\n    SHLI  R7, R4, 3\n    ADD   R6, R6, R7            ; &A[row][0]\n    LDC   R7, c[1]\n    ADD   R7, R7, R5            ; &B[0][col]\n    MOVI  R8, 0                 ; acc\n    MOVI  R9, 0                 ; k\n    MOVI  R13, 8\nkloop:\n    LDG   R10, [R6]             ; A[row][k]\n    LDG   R11, [R7]             ; B[k][col]\n    MAD   R8, R10, R11, R8      ; acc += a * b\n    ADDI  R6, R6, 1\n    ADDI  R7, R7, 8\n    ADDI  R9, R9, 1\n    SETP.LT P0, R9, R13\n@P0 BRA   kloop\n    LDC   R12, c[2]\n    ADD   R12, R12, R3\n    STG   [R12], R8\n    EXIT\n"
 }
];
